using System.Globalization;
using MiniBitcoin.ConsoleApp;
CultureInfo.DefaultThreadCurrentCulture=new CultureInfo("pt-BR");
var wallet=new Wallet(10000m); var quote=new BitcoinQuote(350000m); var exchange=new BitcoinExchange(wallet,quote);
while(true){Console.Clear();Console.WriteLine("========== MINIBITCOIN ==========");Console.WriteLine($"Cotação: {quote.PriceBrl:C} | BRL: {wallet.BalanceBrl:C} | BTC: {wallet.BalanceBtc:N8}");Console.WriteLine($"Patrimônio: {exchange.GetTotalPortfolioBrl():C}\n1-Cotação  2-Atualizar cotação  3-Comprar BTC  4-Vender BTC  5-Extrato  6-Saldos  0-Sair");Console.Write("Opção: ");var op=Console.ReadLine();try{switch(op){case "1":Console.WriteLine($"Cotação atual: {quote.PriceBrl:C}");Pause();break;case "2":quote.Update(Read("Nova cotação: "));Console.WriteLine("Cotação atualizada.");Pause();break;case "3":var buy=exchange.Buy(Read("Valor em BRL: "));Console.WriteLine($"Compra: {buy.BtcAmount:N8} BTC por {buy.BrlAmount:C}");Pause();break;case "4":var sell=exchange.Sell(Read("Quantidade de BTC: "));Console.WriteLine($"Venda: {sell.BtcAmount:N8} BTC por {sell.BrlAmount:C}");Pause();break;case "5":Console.WriteLine("========== EXTRATO ==========");if(exchange.Transactions.Count==0)Console.WriteLine("Nenhuma transação.");foreach(var t in exchange.Transactions)Console.WriteLine($"{t.Date:dd/MM/yyyy HH:mm:ss} | {t.Type} | {t.BtcAmount:N8} BTC | {t.BrlAmount:C} | Cotação {t.BitcoinPriceBrl:C}");Console.WriteLine($"Patrimônio: {exchange.GetTotalPortfolioBrl():C}");Pause();break;case "6":Console.WriteLine($"BRL: {wallet.BalanceBrl:C}\nBTC: {wallet.BalanceBtc:N8}\nTotal: {exchange.GetTotalPortfolioBrl():C}");Pause();break;case "0":return;default:Console.WriteLine("Opção inválida.");Pause();break;}}catch(Exception e) when(e is ArgumentException or InvalidOperationException){Console.WriteLine($"Erro: {e.Message}");Pause();}}
static decimal Read(string msg){while(true){Console.Write(msg);var s=Console.ReadLine()?.Trim().Replace('.',',');if(decimal.TryParse(s,NumberStyles.Number,new CultureInfo("pt-BR"),out var v))return v;Console.WriteLine("Digite um número válido.");}}
static void Pause(){Console.WriteLine("Pressione ENTER...");Console.ReadLine();}
